/** Runs [block] on IO; result is Result so UI can show errors instead of crashing. */
private suspend fun <T> io(block: () -> T) = withContext(Dispatchers.IO) { runCatching(block) }

@Composable
fun App() {
  var patient by rememberSaveable(stateSaver = androidx.compose.runtime.saveable.listSaver(
    save = { listOf(it?.id, it?.name, it?.birth?.toString(), it?.edd?.toString()) },
    restore = { l -> l[0]?.let { Patient(it!!, l[1]!!, LocalDate.parse(l[2]), l[3]?.let(LocalDate::parse)) } }
  )) { mutableStateOf<Patient?>(null) }
  var form by rememberSaveable { mutableStateOf(false) }
  var refresh by remember { mutableIntStateOf(0) }
  BackHandler(patient != null) { if (form) form = false else patient = null }
  val p = patient
